css:
.toolbar { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; margin-bottom: 10px; }
.toolbar button { background: #1e293b; color: #e2e8f0; border: 1px solid #334155; border-radius: 5px; padding: 4px 8px; font-size: 11px; cursor: pointer; }
.toolbar button:hover { border-color: #38bdf8; }
.pos { margin-left: auto; font-size: 11px; color: #38bdf8; }
.track-wrap { position: relative; border: 1px solid #1e293b; border-radius: 8px; background: #0d1016; overflow: hidden; }
.pad-guide { position: absolute; top: 0; bottom: 0; left: var(--scroll-pad, 16px); width: 2px; background: rgba(245, 158, 11, 0.7); pointer-events: none; z-index: 2; }
.track { display: flex; gap: 12px; overflow-x: auto; padding: 16px; scroll-padding-inline-start: var(--scroll-pad, 16px); scroll-behavior: smooth; }
#sandbox-root.snap-mandatory .track { scroll-snap-type: x mandatory; }
#sandbox-root.snap-proximity .track { scroll-snap-type: x proximity; }
#sandbox-root.snap-none .track { scroll-snap-type: none; }
.slide { flex: 0 0 180px; height: 128px; scroll-snap-align: start; border-radius: 8px; border: 1px solid #334155; background: linear-gradient(135deg, rgba(56, 189, 248, 0.14), rgba(15, 23, 42, 0.9)); padding: 12px; display: flex; flex-direction: column; justify-content: space-between; }
#sandbox-root.stop-always .slide { scroll-snap-stop: always; border-color: #34d399; }
.slide strong { font-size: 22px; color: #f8fafc; }
.slide span { font-size: 11px; color: #94a3b8; }
